/**
 * Accept invitation page.
 *
 * Server component: loads the caller's own invitation by id via the
 * bound team service (`@/lib/team`, installed by the `team-settings`
 * registry item) and renders one of three reachable states.
 *
 * A note on state coverage: `team.getUserInvitations()` is the only
 * read this item's dependency (the team service in `@intelligo-dev/auth`)
 * exposes for this page. It wraps Better-Auth's
 * `/organization/list-user-invitations` endpoint, which the
 * organization plugin pre-filters to `status === "pending"` before it
 * ever reaches the service. That means an invitation id that does not
 * turn up in the list is indistinguishable, from here, between "never
 * existed", "belongs to a different account", and "already
 * accepted/declined/canceled elsewhere" — there is no by-id read on
 * the service that surfaces a non-pending invitation's status. The
 * "Invitation unavailable" state below covers all three honestly
 * rather than fabricating a distinction the data cannot support.
 * "Expired" IS reliably reachable: the endpoint filters on `status`,
 * not on `expiresAt`, so a past-due invitation still comes back in the
 * list and this page compares the timestamp itself.
 */

import { getFormatter, getTranslations } from "next-intl/server";

import { requireAuth } from "@intelligo-dev/auth";

import { Alert, AlertDescription } from "@/components/ui/alert";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { RoleBadge } from "@/components/team/role-badge";
import { InvitationActions } from "@/components/invitation/invitation-actions";
import { team } from "@/lib/team";

interface Props {
  params: Promise<{ id: string }>;
}

function StatusCard({
  title,
  description,
}: {
  title: string;
  description: string;
}) {
  return (
    <div className="flex min-h-[60vh] items-center justify-center p-4">
      <Card className="w-full max-w-md">
        <CardHeader>
          <CardTitle>{title}</CardTitle>
        </CardHeader>
        <CardContent>
          <Alert variant="destructive">
            <AlertDescription>{description}</AlertDescription>
          </Alert>
        </CardContent>
      </Card>
    </div>
  );
}

export default async function AcceptInvitationPage({ params }: Props) {
  const t = await getTranslations("invitation-accept");
  const format = await getFormatter();
  await requireAuth();
  const { id } = await params;

  const invitations = await team.getUserInvitations();
  const invitation = invitations.find((inv) => inv.id === id);

  if (!invitation) {
    return (
      <StatusCard
        title={t("unavailable.title")}
        description={t("unavailable.description")}
      />
    );
  }

  const isExpired = new Date(invitation.expiresAt) < new Date();

  if (isExpired) {
    return (
      <StatusCard
        title={t("expired.title")}
        description={t("expired.description")}
      />
    );
  }

  return (
    <div className="flex min-h-[60vh] items-center justify-center p-4">
      <Card className="w-full max-w-md">
        <CardHeader>
          <CardTitle>{t("card.title")}</CardTitle>
          <CardDescription>{t("card.description")}</CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="space-y-4">
            <div>
              <p className="text-sm font-medium text-muted-foreground">
                {t("card.workspaceLabel")}
              </p>
              <p className="text-base font-semibold">
                {invitation.organizationName ?? t("card.workspaceFallback")}
              </p>
            </div>

            <div>
              <p className="text-sm font-medium text-muted-foreground">
                {t("card.invitedByLabel")}
              </p>
              <p className="text-base">
                {invitation.inviterEmail ?? t("card.invitedByFallback")}
              </p>
            </div>

            <div>
              <p className="text-sm font-medium text-muted-foreground">
                {t("card.roleLabel")}
              </p>
              <div className="mt-1">
                <RoleBadge role={invitation.role} />
              </div>
            </div>

            <div>
              <p className="text-sm font-medium text-muted-foreground">
                {t("card.expiresLabel")}
              </p>
              <p className="text-base">
                {format.dateTime(new Date(invitation.expiresAt), {
                  dateStyle: "medium",
                })}
              </p>
            </div>
          </div>

          <InvitationActions invitationId={invitation.id} />
        </CardContent>
      </Card>
    </div>
  );
}

/**
 * Loading skeleton for the invitation-accept page.
 */

import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";

export default function AcceptInvitationLoading() {
  return (
    <div className="flex min-h-[60vh] items-center justify-center p-4">
      <Card className="w-full max-w-md">
        <CardHeader>
          <Skeleton className="mb-2 h-7 w-48" />
          <Skeleton className="h-4 w-64" />
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="space-y-4">
            {[1, 2, 3, 4].map((i) => (
              <div key={i}>
                <Skeleton className="mb-1 h-4 w-20" />
                <Skeleton className="h-5 w-full" />
              </div>
            ))}
          </div>

          <div className="flex gap-2">
            <Skeleton className="h-10 flex-1" />
            <Skeleton className="h-10 flex-1" />
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

/**
 * Client error boundary for the invitation-accept route.
 *
 * Self-contained: registry items ship consumer-owned, translated copy
 * with no dependency beyond `@/components/ui/*` (ADR-0010), so this
 * does not reach for an app-internal shared error component or an
 * error reporting SDK.
 */

import { useEffect } from "react";
import { useTranslations } from "next-intl";

import { Link } from "@/i18n/navigation";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

export default function AcceptInvitationError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  const t = useTranslations("invitation-accept");

  useEffect(() => {
    console.error("[accept-invitation] error boundary caught:", error);
  }, [error]);

  return (
    <div className="flex min-h-[60vh] items-center justify-center p-4">
      <div className="w-full max-w-md space-y-4">
        <Alert variant="destructive">
          <AlertDescription>{t("errorBoundary.message")}</AlertDescription>
        </Alert>

        <div className="flex justify-center gap-3">
          <Button onClick={reset}>{t("errorBoundary.retry")}</Button>
          <Button
            variant="outline"
            render={<Link href="/" />}
            nativeButton={false}
          >
            {t("errorBoundary.goHome")}
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

/**
 * Accept/decline buttons for the invitation-accept page.
 */

import { useState } from "react";
import { useTranslations } from "next-intl";
import { toast } from "sonner";

import { useRouter } from "@/i18n/navigation";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { acceptInvitation, rejectInvitation } from "@/actions/invitation";

interface InvitationActionsProps {
  invitationId: string;
}

export function InvitationActions({ invitationId }: InvitationActionsProps) {
  const t = useTranslations("invitation-accept");
  const router = useRouter();
  const [error, setError] = useState<string | null>(null);
  const [isAccepting, setIsAccepting] = useState(false);
  const [isDeclining, setIsDeclining] = useState(false);

  async function handleAccept() {
    setError(null);
    setIsAccepting(true);

    const result = await acceptInvitation(invitationId);

    if (!result.success) {
      setError(result.error);
      toast.error(result.error);
      setIsAccepting(false);
      return;
    }

    router.push("/");
    router.refresh();
  }

  async function handleDecline() {
    setError(null);
    setIsDeclining(true);

    const result = await rejectInvitation(invitationId);

    if (!result.success) {
      setError(result.error);
      toast.error(result.error);
      setIsDeclining(false);
      return;
    }

    router.push("/");
    router.refresh();
  }

  const isPending = isAccepting || isDeclining;

  return (
    <div className="space-y-4">
      {error && (
        <Alert variant="destructive">
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}

      <div className="flex gap-3">
        <Button onClick={handleAccept} disabled={isPending} size="lg">
          {isAccepting ? t("actions.acceptPending") : t("actions.accept")}
        </Button>
        <Button
          onClick={handleDecline}
          disabled={isPending}
          variant="outline"
          size="lg"
        >
          {isDeclining ? t("actions.declinePending") : t("actions.decline")}
        </Button>
      </div>
    </div>
  );
}

"use server";

/**
 * Invitation accept/decline server actions.
 *
 * Thin transport over `@intelligo-dev/auth`'s team service, bound with
 * this consumer's ports at `@/lib/team` (installed by the
 * `team-settings` registry item — see its module doc for the exact
 * port bindings). All authorization, invitation-ownership checks, and
 * post-accept membership verification live in the service; this file
 * only calls it, maps a thrown `TeamServiceError` to a friendly
 * message, and revalidates the paths that show invitation/membership
 * state.
 */

import { revalidatePath } from "next/cache";
import { getTranslations } from "next-intl/server";

import {
  isTeamServiceError,
  type TeamServiceErrorCode,
} from "@intelligo-dev/auth";

import { team } from "@/lib/team";

export type InvitationActionResult =
  | { success: true }
  | { success: false; error: string };

type Translator = Awaited<
  ReturnType<typeof getTranslations<"invitation-accept">>
>;

function friendlyMessages(
  t: Translator
): Partial<Record<TeamServiceErrorCode, string>> {
  return {
    invitation_not_found: t("errors.invitationNotFound"),
    accept_verification_failed: t("errors.acceptVerificationFailed"),
    forbidden: t("errors.forbidden"),
    invalid_input: t("errors.invalidInput"),
    provider_error: t("errors.providerError"),
  };
}

function toMessage(error: unknown, fallback: string, t: Translator): string {
  if (isTeamServiceError(error)) {
    return friendlyMessages(t)[error.code] ?? fallback;
  }
  return fallback;
}

export async function acceptInvitation(
  invitationId: string
): Promise<InvitationActionResult> {
  const t = await getTranslations("invitation-accept");
  try {
    await team.acceptInvitation(invitationId);
  } catch (error) {
    return {
      success: false,
      error: toMessage(error, t("errors.acceptFailed"), t),
    };
  }

  revalidatePath("/accept-invitation/[id]", "page");
  revalidatePath("/settings/team");
  revalidatePath("/");
  return { success: true };
}

export async function rejectInvitation(
  invitationId: string
): Promise<InvitationActionResult> {
  const t = await getTranslations("invitation-accept");
  try {
    await team.rejectInvitation(invitationId);
  } catch (error) {
    return {
      success: false,
      error: toMessage(error, t("errors.declineFailed"), t),
    };
  }

  revalidatePath("/accept-invitation/[id]", "page");
  return { success: true };
}

